package ncasa.notification.application;
import ncasa.notification.application.port.out.*;import ncasa.notification.domain.AccountRef;
public final class ListNotificationsUseCase{private final NotificationRepository notifications;private final HouseholdNotificationDirectoryPort households;public ListNotificationsUseCase(NotificationRepository n,HouseholdNotificationDirectoryPort h){notifications=n;households=h;}public NotificationPage execute(Long account,boolean unreadOnly,int page,int size){if(page<0)throw new IllegalArgumentException("Page cannot be negative");if(size<1||size>50)throw new IllegalArgumentException("Size must be between 1 and 50");var slice=notifications.findPage(new AccountRef(account),NotificationAccess.households(households,account),unreadOnly,page,size);return new NotificationPage(slice.content().stream().map(NotificationView::from).toList(),page,size,slice.totalElements(),(int)Math.ceil((double)slice.totalElements()/size));}}
